import { getProducts, syncProductsInBackground } from '@/lib/products';
import { revalidateTag } from 'next/cache';

export default async function AdminCatalogPage() {
  const products = await getProducts();

  // Inline Server Action for syncing catalog
  async function syncCatalog() {
    'use server';

    // Trigger background sync without blocking
    syncProductsInBackground().then(() => {
      // Invalidate the 'products' cache tag after sync completes
      revalidateTag('products');
    });

    // Return immediately so admin can continue working
    return { success: true, message: 'Sync started in background' };
  }

  return (
    <div style={{ padding: '2rem', maxWidth: '1200px', margin: '0 auto' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '2rem' }}>
        <h1 style={{ fontSize: '2rem', fontWeight: 'bold' }}>Product Catalog</h1>

        {/* Sync trigger form */}
        <form action={syncCatalog}>
          <button
            type="submit"
            style={{
              padding: '0.5rem 1rem',
              backgroundColor: '#0070f3',
              color: 'white',
              border: 'none',
              borderRadius: '0.25rem',
              cursor: 'pointer',
              fontSize: '0.875rem',
              fontWeight: '500'
            }}
          >
            Sync latest catalog
          </button>
        </form>
      </div>

      <div style={{ fontSize: '0.875rem', color: '#666', marginBottom: '1rem' }}>
        Showing {products.length} products
      </div>

      {/* Product table */}
      <div style={{ border: '1px solid #e5e7eb', borderRadius: '0.5rem', overflow: 'hidden' }}>
        <table style={{ width: '100%', borderCollapse: 'collapse' }}>
          <thead style={{ backgroundColor: '#f9fafb' }}>
            <tr>
              <th style={{ padding: '0.75rem', textAlign: 'left', fontSize: '0.75rem', fontWeight: '600', textTransform: 'uppercase', color: '#6b7280' }}>
                SKU
              </th>
              <th style={{ padding: '0.75rem', textAlign: 'left', fontSize: '0.75rem', fontWeight: '600', textTransform: 'uppercase', color: '#6b7280' }}>
                Product Name
              </th>
              <th style={{ padding: '0.75rem', textAlign: 'right', fontSize: '0.75rem', fontWeight: '600', textTransform: 'uppercase', color: '#6b7280' }}>
                Price
              </th>
              <th style={{ padding: '0.75rem', textAlign: 'right', fontSize: '0.75rem', fontWeight: '600', textTransform: 'uppercase', color: '#6b7280' }}>
                Inventory
              </th>
              <th style={{ padding: '0.75rem', textAlign: 'center', fontSize: '0.75rem', fontWeight: '600', textTransform: 'uppercase', color: '#6b7280' }}>
                Status
              </th>
              <th style={{ padding: '0.75rem', textAlign: 'left', fontSize: '0.75rem', fontWeight: '600', textTransform: 'uppercase', color: '#6b7280' }}>
                Last Updated
              </th>
            </tr>
          </thead>
          <tbody>
            {products.map((product, index) => (
              <tr
                key={product.id}
                style={{
                  borderTop: index === 0 ? 'none' : '1px solid #e5e7eb',
                  backgroundColor: index % 2 === 0 ? 'white' : '#f9fafb'
                }}
              >
                <td style={{ padding: '1rem', fontSize: '0.875rem', fontFamily: 'monospace', color: '#374151' }}>
                  {product.sku}
                </td>
                <td style={{ padding: '1rem', fontSize: '0.875rem', color: '#111827', fontWeight: '500' }}>
                  {product.name}
                </td>
                <td style={{ padding: '1rem', fontSize: '0.875rem', textAlign: 'right', color: '#111827' }}>
                  ${product.price.toFixed(2)}
                </td>
                <td style={{ padding: '1rem', fontSize: '0.875rem', textAlign: 'right', color: product.inventory === 0 ? '#dc2626' : '#111827' }}>
                  {product.inventory}
                </td>
                <td style={{ padding: '1rem', textAlign: 'center' }}>
                  <span
                    style={{
                      padding: '0.25rem 0.5rem',
                      fontSize: '0.75rem',
                      fontWeight: '500',
                      borderRadius: '9999px',
                      backgroundColor: product.available ? '#d1fae5' : '#fee2e2',
                      color: product.available ? '#065f46' : '#991b1b'
                    }}
                  >
                    {product.available ? 'Available' : 'Out of Stock'}
                  </span>
                </td>
                <td style={{ padding: '1rem', fontSize: '0.875rem', color: '#6b7280' }}>
                  {product.lastUpdated.toLocaleString()}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <div style={{ marginTop: '1.5rem', padding: '1rem', backgroundColor: '#f0f9ff', borderLeft: '4px solid #0ea5e9', borderRadius: '0.25rem' }}>
        <p style={{ fontSize: '0.875rem', color: '#0c4a6e' }}>
          <strong>Note:</strong> Clicking "Sync latest catalog" triggers a background refresh.
          You can continue working immediately. Data will update shortly across all views.
        </p>
      </div>
    </div>
  );
}

